function basketRange(TradingContextP0 memory ctx, IERC20[] memory erc20s)
        internal
        view
        returns (BasketRange memory range)
    {
        (uint192 buPriceLow, uint192 buPriceHigh) = ctx.bh.price(false); // {UoA/BU}

