                    IERC20Upgradeable(address(erc20)).safeTransferFrom(
                        caller,
                        recipient,
                        tokensPerShare * (totalShares - paidOutShares)
                    );
                }
            }
        }

        // Perform reward accounting
        if (accountRewards) {
            if (isRSR) {
                stRSR.payoutRewards();
            } else {
                furnace.melt();
            }
        }
    }

