    //   else: sell erc20 for tokenToBuy
    function manageTokens(IERC20[] calldata erc20s, TradeKind[] calldata kinds)
        external
        globalNonReentrant
        notTradingPausedOrFrozen
    {
        uint256 len = erc20s.length;
