            if (erc20s[i] == IERC20(address(rToken))) involvesRToken = true;
            if (erc20s[i] == tokenToBuy) {
                _distributeTokenToBuy();
                if (len == 1) return; // return early if tokenToBuy is only entry
            }
        }

