    /// @return high {UoA/tok} The high price estimate
    function tryPrice()
        external
        view
        virtual
        override
        returns (
            uint192 low,
            uint192 high,
            uint192
        )
    {
        // Note: "ref" in this context refers to ETH, used as intermediate pricing unit
