    function _getVotes(
        address account,
        uint256 timepoint,
        bytes memory /*params*/
    ) internal view override(Governor, GovernorVotes) returns (uint256) {
        return token.getPastVotes(account, timepoint); // {qStRSR}
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
